window.RP_SESSION={"id":"S-07fdf574d9e8","messages":[{"id":"RP-II-0098024","time":"2026-05-06T20:00:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"안녕. 처음 보는 이방인.\n\n당신의 일생이 어땠을까 가만히 상상하곤 했는데. 아마 당신도 기억에 남을 모험가였겠지. 누군가를 구하기 위해, 혹은 숭고한 무언가를 하기 위해 안전을 내려놓는 삶을 얼마나 보냈을까. 듣기로는 새하얀 털의 토끼였다고 들었는데.\n\n언제나 이별은 모두에게 힘들테지. 마음에 품지 않은 사람도, 품은 사람도. 전부 어쩌다 당신을 떠올릴거야.\n\n그들 모두가 당신 몫만큼 당신의 삶을 그리워할테니.\n\n이방인, 부디 당신은 후회하지 마.","characters":[]},{"id":"RP-II-0098025","time":"2026-05-06T20:07:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"잿더미 속에서도 피어나려 노력하는 것이 새싹이고, 그 속에서도 살고자 하는 것이 생명이니까.\n\n당신의 추억을 영양 삼아, 나침반 삼아 제 길을 나아갈 존재가 많으니.\n\n부디 당신의 재는 당신을 기억하는 모두에게 길을 잡아줄 기준이 되어주기를.","characters":[]},{"id":"RP-II-0098026","time":"2026-05-06T20:08:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"잘자, 다음 당신의 모험도 이 생의 모험처럼 도움리 되기를.\n\n나중에 또 그들을 찾으러 와, 이방인.","characters":[]},{"id":"RP-II-0098027","time":"2026-05-06T20:08:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0098028","time":"2026-05-06T20:08:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-II-0098029","time":"2026-05-06T23:33:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"!모닥불","characters":[]},{"id":"RP-II-0098030","time":"2026-05-06T23:33:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]}]};
